// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);
        vm.roll(blockNum);
        vm.warp(warpTime);
        address sender = address(0x1234);
        uint256 value = 10 ether;
        vm.deal(sender, value);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: value}("");
        require(ok, "call failed");
        uint256 balance = address(c).balance;
        if (blockNum % 15 == 0) {
            assertTrue(balance == 0);
        } else {
            assertTrue(balance > 0);
        }
    }
}
